param([Parameter(Mandatory=$true)][string]$Dir)
$ErrorActionPreference='Stop';$existing=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|ForEach-Object{[int]$_.ProcessId});$owned=@();$w=New-Object -ComObject Word.Application;$w.Visible=$false;$w.DisplayAlerts=0
try{$d=$w.Documents.Add();$owned=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId});if(-not $owned.Count){throw 'Word COM PID missing'};$d.Content.Text='Shape audit';$shape=$d.Shapes.AddShape(1,147,192,105,60);$shape.Fill.ForeColor.RGB=15426341;$shape.Line.ForeColor.RGB=14175773;$shape.Line.Weight=1.5;$d.SaveAs2("$Dir\word_shapes_t8_new.docx",16);$d.Close(0);foreach($name in @('word_shapes_t8_new.docx','app_shapes_t8_new.docx')){$d=$w.Documents.Open("$Dir\$name",$false,$true);try{$rows=@();foreach($s in $d.Shapes){$rows+=('{0}|{1}|{2}|{3}|{4}|{5}|{6}|{7}' -f [int]$s.Type,[math]::Round([double]$s.Width,1),[math]::Round([double]$s.Height,1),[math]::Round([double]$s.Left,1),[math]::Round([double]$s.Top,1),$s.Fill.ForeColor.RGB,$s.Line.ForeColor.RGB,[math]::Round([double]$s.Line.Weight,1))};Write-Output ("{0}: shapes={1}; {2}" -f $name,$d.Shapes.Count,($rows -join '; '))}finally{$d.Close(0)}}
}finally{if($w){$w.Quit();[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($w)};$owned=@($owned+@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId})|Select-Object -Unique);foreach($ownedPid in $owned){$p=Get-Process -Id $ownedPid -ErrorAction SilentlyContinue;if($p){$p|Wait-Process -Timeout 3 -ErrorAction SilentlyContinue};if(Get-Process -Id $ownedPid -ErrorAction SilentlyContinue){Stop-Process -Id $ownedPid -Force -ErrorAction SilentlyContinue}}}
